/* =====================================================================
   강좌별 가격 · 수강 기간 · 교재 가격
   - 각 사이트(메가스터디·이투스·대성마이맥) 강좌 목록·상세 페이지에서 확인한 값 (2026-11-09 기준)
   - 형식: { "선생님": [ { t: 강좌명, p: 가격, d: 수강기간, b: 교재 } ] }
   - index.html 이 강좌명을 비교해서 '강좌 리스트'의 각 강좌 옆에 표시함
   ===================================================================== */
window.COURSE_PRICES = window.COURSE_PRICES || {};

function addCoursePrices(obj) {
  const dec = s => s == null ? null : String(s)
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&amp;/g, '&');
  Object.keys(obj).forEach(name => {
    window.COURSE_PRICES[dec(name)] = obj[name].map(e => ({
      t: dec(e.t),
      p: dec(e.p),
      // "132일(배송)" → "132일 (교재 배송기간 포함)"
      d: e.d ? dec(e.d).replace(/\s*\(배송\)/, ' (교재 배송기간 포함)') : null,
      b: dec(e.b)
    }));
  });
}

